import{_ as d,o as e,c as o,ah as r}from"./chunks/framework.DjU4PSOm.js";const g=JSON.parse('{"title":"Zing 기능 명세서","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 화면 목록","slug":"_1-화면-목록","link":"#_1-화면-목록","children":[{"level":3,"title":"화면 흐름 (2026-10-02 추가)","slug":"화면-흐름-2026-10-02-추가","link":"#화면-흐름-2026-10-02-추가","children":[]}]},{"level":2,"title":"2. 데이터 모델 (테이블 스키마)","slug":"_2-데이터-모델-테이블-스키마","link":"#_2-데이터-모델-테이블-스키마","children":[{"level":3,"title":"users","slug":"users","link":"#users","children":[]},{"level":3,"title":"diaries","slug":"diaries","link":"#diaries","children":[]},{"level":3,"title":"RLS 정책 (2026-09-19)","slug":"rls-정책-2026-09-19","link":"#rls-정책-2026-09-19","children":[]},{"level":3,"title":"zings (매칭)","slug":"zings-매칭","link":"#zings-매칭","children":[]},{"level":3,"title":"prompts (글감, 도입 여부 미정)","slug":"prompts-글감-도입-여부-미정","link":"#prompts-글감-도입-여부-미정","children":[]},{"level":3,"title":"messages","slug":"messages","link":"#messages","children":[]}]},{"level":2,"title":"3. API 계약 (함수 시그니처)","slug":"_3-api-계약-함수-시그니처","link":"#_3-api-계약-함수-시그니처","children":[{"level":3,"title":"signUp 상세","slug":"signup-상세","link":"#signup-상세","children":[]},{"level":3,"title":"signIn 상세","slug":"signin-상세","link":"#signin-상세","children":[]}]},{"level":2,"title":"4. 정책/제약 규칙 (미정 항목 — 확정되면 여기 기록)","slug":"_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록","link":"#_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록","children":[]},{"level":2,"title":"5. 비즈니스 모델 (BM) — 방향 확정 (2026-10-02), 세부 수치 미정","slug":"_5-비즈니스-모델-bm-—-방향-확정-2026-10-02-세부-수치-미정","link":"#_5-비즈니스-모델-bm-—-방향-확정-2026-10-02-세부-수치-미정","children":[{"level":3,"title":"전략: 핵심 무료 + 부가 기능 유료, 초기엔 전부 무료로 런칭","slug":"전략-핵심-무료-부가-기능-유료-초기엔-전부-무료로-런칭","link":"#전략-핵심-무료-부가-기능-유료-초기엔-전부-무료로-런칭","children":[]},{"level":3,"title":"참고 — 비용 구조상 자연스러운 안전장치","slug":"참고-—-비용-구조상-자연스러운-안전장치","link":"#참고-—-비용-구조상-자연스러운-안전장치","children":[]}]}],"relativePath":"computer/project/Zing/기능명세서.md","filePath":"computer/project/Zing/기능명세서.md"}'),a={name:"computer/project/Zing/기능명세서.md"};function l(i,t,n,s,c,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="zing-기능-명세서" tabindex="-1">Zing 기능 명세서 <a class="header-anchor" href="#zing-기능-명세서" aria-label="Permalink to &quot;Zing 기능 명세서&quot;">​</a></h1><p>병렬 작업(백엔드/프론트) 시 서로 안 부딪히기 위한 기준 문서. 항목이 바뀌면 여기부터 업데이트하고, 코드는 그 기준을 따라간다.</p><h2 id="_1-화면-목록" tabindex="-1">1. 화면 목록 <a class="header-anchor" href="#_1-화면-목록" aria-label="Permalink to &quot;1. 화면 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>화면</th><th>설명</th></tr></thead><tbody><tr><td>회원가입</td><td>계정 생성, 성별 비공개(자율 선택)</td></tr><tr><td>로그인</td><td>이메일+비밀번호 로그인</td></tr><tr><td>일기 작성</td><td>200~600자 검증</td></tr><tr><td>피드</td><td>랜덤 일기 넘겨보기, 징 보내기</td></tr><tr><td>매칭 목록</td><td>상호 징 성사된 상대 목록</td></tr><tr><td>상대방 일기 상세</td><td>매칭된 상대 일기, 반응/댓글</td></tr><tr><td>프로필</td><td>내 정보 관리</td></tr><tr><td>채팅</td><td>제한적 소통 (로드맵 마지막 단계)</td></tr><tr><td>알림</td><td>매칭 성사/반응 등 이벤트</td></tr></tbody></table><p>(화면별 와이어프레임은 Figma 참고 — 링크 추가 예정)</p><h3 id="화면-흐름-2026-10-02-추가" tabindex="-1">화면 흐름 (2026-10-02 추가) <a class="header-anchor" href="#화면-흐름-2026-10-02-추가" aria-label="Permalink to &quot;화면 흐름 (2026-10-02 추가)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>회원가입 ──┐</span></span>\n<span class="line"><span>          ├──&gt; 로그인 ──&gt; 피드(홈) ──┬──&gt; 일기 작성</span></span>\n<span class="line"><span>          │                        ├──&gt; 상대방 일기 상세 ──&gt; (징 보내기)</span></span>\n<span class="line"><span>          │                        ├──&gt; 매칭 목록 ──&gt; 채팅</span></span>\n<span class="line"><span>          │                        ├──&gt; 프로필</span></span>\n<span class="line"><span>          │                        └──&gt; 알림</span></span>\n<span class="line"><span>          └──────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><ul><li>회원가입/로그인 → 피드가 시작점. 피드에서 다른 화면들로 분기.</li><li>채팅은 매칭 목록에서 상대 선택 후 진입 (매칭 안 된 상대랑은 채팅 불가).</li><li>일기 작성은 피드에서 바로 진입 (탭 또는 버튼).</li></ul><h2 id="_2-데이터-모델-테이블-스키마" tabindex="-1">2. 데이터 모델 (테이블 스키마) <a class="header-anchor" href="#_2-데이터-모델-테이블-스키마" aria-label="Permalink to &quot;2. 데이터 모델 (테이블 스키마)&quot;">​</a></h2><blockquote><p>아래는 초안. 실제 Supabase 테이블 만들 때 이 표부터 채우고 시작.</p></blockquote><h3 id="users" tabindex="-1"><code>users</code> <a class="header-anchor" href="#users" aria-label="Permalink to &quot;`users`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td>PK, <code>auth.users.id</code> 참조 FK (2026-09-19, 대시보드에서 수동 설정, ON DELETE CASCADE — Auth 계정 삭제 시 프로필도 자동 삭제됨)</td></tr><tr><td>nickname</td><td>text</td><td>화면에 보여줄 이름 (실명 아님)</td></tr><tr><td>gender</td><td>text | null</td><td><code>&#39;male&#39;</code> | <code>&#39;female&#39;</code> | <code>null</code>(비공개, 자율 선택)</td></tr><tr><td>is_exchange_student</td><td>boolean</td><td>교환학생 여부 — 매칭/번역 방향 결정에 필요</td></tr><tr><td>nationality</td><td>text</td><td>국적, 필수 — 매칭 상대의 문화적 배경을 아는 것이 서비스 핵심 가치라 비공개 옵션 없음(성별과 다름)</td></tr><tr><td>preferred_language</td><td>text</td><td>일기 작성/번역 기준 언어 (예: <code>&#39;ko&#39;</code>, <code>&#39;en&#39;</code>)</td></tr><tr><td>profile_image_url</td><td>text | null</td><td>프로필 이미지 (없으면 기본 이미지)</td></tr><tr><td>created_at</td><td>timestamp</td><td>가입일</td></tr></tbody></table><h3 id="diaries" tabindex="-1"><code>diaries</code> <a class="header-anchor" href="#diaries" aria-label="Permalink to &quot;`diaries`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td>PK</td></tr><tr><td>author_id</td><td>uuid</td><td>FK → <code>users.id</code></td></tr><tr><td>content</td><td>text</td><td>200~600자 검증 (프론트+DB 양쪽에서 체크)</td></tr><tr><td>char_count</td><td>int</td><td><code>content</code> 글자 수 (검증/표시용으로 별도 저장)</td></tr><tr><td>created_at</td><td>timestamp</td><td>작성일</td></tr><tr><td>updated_at</td><td>timestamp | null</td><td>수정 시 갱신</td></tr></tbody></table><blockquote><p><strong>미정</strong>: &quot;매칭 전 절반만 공개&quot; 로직을 위한 필드는 아직 안 넣음 — 글자 수 기준인지 문단 기준인지(09-03 노트 미정 항목) 정해지면 그때 <code>public_preview</code> 같은 필드 또는 앱 로직(예: <code>content.slice(0, N)</code>)으로 처리할지 결정.</p></blockquote><blockquote><p><strong>[x] 확정 (2026-10-02): 일기 하루 1개 제한.</strong> 단계적 소통 해금(섹션 4)을 &quot;매칭 이후 작성한 일기 개수&quot;로 판단하기로 하면서 같이 필요해진 규칙 — 제한 없으면 한 번에 여러 개 몰아 써서 해금 단계를 부정하게 빨리 통과할 수 있음. <code>createDiary</code>에서 &quot;오늘 날짜로 이미 작성한 일기가 있는지&quot; 체크 후 있으면 에러 리턴하도록 구현 예정 (아직 코드 미반영).</p></blockquote><h3 id="rls-정책-2026-09-19" tabindex="-1">RLS 정책 (2026-09-19) <a class="header-anchor" href="#rls-정책-2026-09-19" aria-label="Permalink to &quot;RLS 정책 (2026-09-19)&quot;">​</a></h3><p><code>users</code> 테이블 실제 동작 확인 중, <code>signUp</code> 테스트가 계속 403으로 막힌 문제를 디버깅해서 찾은 결론.</p><ul><li><code>Users can insert own profile</code> — INSERT, <code>to authenticated</code>, <code>with check (auth.uid() = id)</code></li><li><code>Users can view own profile</code> — SELECT, <code>to authenticated</code>, <code>using (auth.uid() = id)</code></li></ul><blockquote><p><strong>중요 교훈</strong>: <code>.insert(...).select()</code>처럼 insert 후 결과를 바로 조회하는 코드는 <strong>INSERT 정책뿐 아니라 SELECT 정책도 있어야</strong> 동작한다. SELECT 정책이 없으면 INSERT 자체는 성공해도, 결과를 돌려주는 단계(<code>RETURNING</code>)에서 막히면서 <strong>INSERT 정책 위반과 똑같은 403/RLS 에러 메시지</strong>가 떠서 원인 파악이 헷갈리기 쉽다. 앞으로 테이블 만들 때마다 CRUD로 실제 쓰는 동작(insert, select, update, delete) 각각에 맞는 정책을 다 챙겨야 함 — <code>diaries</code> 등 다른 테이블도 마찬가지로 필요.</p></blockquote><h3 id="zings-매칭" tabindex="-1"><code>zings</code> (매칭) <a class="header-anchor" href="#zings-매칭" aria-label="Permalink to &quot;`zings` (매칭)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td>PK</td></tr><tr><td>sender_id</td><td>uuid</td><td>FK → <code>users.id</code>, 징을 보낸 사람</td></tr><tr><td>receiver_id</td><td>uuid</td><td>FK → <code>users.id</code>, 징을 받은 사람</td></tr><tr><td>created_at</td><td>timestamp</td><td>징 보낸 시각</td></tr><tr><td>matched_at</td><td>timestamp | null</td><td>상호 성사 시각 (양쪽 다 보냈을 때 채워짐, null이면 아직 짝사랑 상태)</td></tr></tbody></table><blockquote><p>동시 매칭 인원 상한(기본 3명 + 4단계 도달 매칭당 +1명, 섹션 4 참고) 체크는 <code>sendZing</code> 함수 안에서 구현 예정 (아직 <code>zings</code> 테이블/함수 자체가 안 만들어짐).</p></blockquote><h3 id="prompts-글감-도입-여부-미정" tabindex="-1"><code>prompts</code> (글감, 도입 여부 미정) <a class="header-anchor" href="#prompts-글감-도입-여부-미정" aria-label="Permalink to &quot;`prompts` (글감, 도입 여부 미정)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead></table><blockquote><p>기능 자체 도입 여부가 미정이라 필드도 비워둠 (섹션 4 참고). 도입 확정되면 <code>content</code>, <code>date</code>(어느 날짜용 글감인지) 정도부터 시작.</p></blockquote><h3 id="messages" tabindex="-1"><code>messages</code> <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;`messages`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td>PK</td></tr><tr><td>zing_id</td><td>uuid</td><td>FK → <code>zings.id</code>, 어느 매칭 대화인지</td></tr><tr><td>sender_id</td><td>uuid</td><td>FK → <code>users.id</code></td></tr><tr><td>content</td><td>text</td><td>메시지 내용</td></tr><tr><td>created_at</td><td>timestamp</td><td>발송 시각</td></tr></tbody></table><blockquote><p><strong>미정</strong>: 하루 메시지 횟수 제한, 텍스트 전용 여부 등(섹션 4) — 필드 자체는 채팅 범위랑 무관하게 안 바뀔 것 같아서 먼저 정의함.</p></blockquote><h2 id="_3-api-계약-함수-시그니처" tabindex="-1">3. API 계약 (함수 시그니처) <a class="header-anchor" href="#_3-api-계약-함수-시그니처" aria-label="Permalink to &quot;3. API 계약 (함수 시그니처)&quot;">​</a></h2><blockquote><p>백엔드가 프론트에 제공하는 함수 목록. 이름/파라미터/리턴값을 여기서 먼저 정하고 나서 구현.</p></blockquote><table tabindex="0"><thead><tr><th>함수</th><th>파라미터</th><th>리턴</th><th>설명</th></tr></thead><tbody><tr><td><code>signUp</code></td><td><code>{ email, password, nickname, gender, isExchangeStudent, nationality, preferredLanguage }</code></td><td><code>{ data, error }</code></td><td>회원가입. Auth 계정 생성 + <code>users</code> 테이블에 프로필 row 생성까지 한 번에 처리</td></tr><tr><td><code>signIn</code></td><td><code>{ email, password }</code></td><td><code>{ data, error }</code></td><td>로그인</td></tr><tr><td><code>createDiary</code></td><td><code>{ content }</code></td><td><code>{ data, error }</code></td><td>일기 작성 (글자수 검증 포함)</td></tr><tr><td><code>getDiaries</code></td><td><code>{ authorId }</code></td><td><code>{ data: Diary[], error }</code></td><td>특정 유저의 일기 목록 조회</td></tr><tr><td><code>updateDiary</code></td><td><code>{ id, content }</code></td><td><code>{ data, error }</code></td><td>내가 쓴 일기 수정 (글자수 재검증)</td></tr><tr><td><code>deleteDiary</code></td><td><code>{ id }</code></td><td><code>{ data, error }</code></td><td>내가 쓴 일기 삭제</td></tr><tr><td><code>getFeed</code></td><td><code>{ userId }</code></td><td><code>{ data: Diary[], error }</code></td><td>랜덤 피드 목록</td></tr><tr><td><code>sendZing</code></td><td><code>{ toUserId }</code></td><td><code>{ data, error }</code></td><td>징 보내기</td></tr><tr><td><code>getMatches</code></td><td><code>{ userId }</code></td><td><code>{ data: Match[], error }</code></td><td>매칭 목록</td></tr></tbody></table><p>(실제 구현하면서 계속 추가)</p><h3 id="signup-상세" tabindex="-1"><code>signUp</code> 상세 <a class="header-anchor" href="#signup-상세" aria-label="Permalink to &quot;`signUp` 상세&quot;">​</a></h3><p><strong>파라미터</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td>email</td><td>string</td><td>O</td><td>로그인용 이메일</td></tr><tr><td>password</td><td>string</td><td>O</td><td>비밀번호</td></tr><tr><td>nickname</td><td>string</td><td>O</td><td>화면에 보여줄 이름</td></tr><tr><td>gender</td><td><code>&#39;male&#39;</code> | <code>&#39;female&#39;</code> | <code>null</code></td><td>X</td><td>비공개 선택 시 <code>null</code></td></tr><tr><td>isExchangeStudent</td><td>boolean</td><td>O</td><td>교환학생 여부</td></tr><tr><td>nationality</td><td>string</td><td>O</td><td>국적</td></tr><tr><td>preferredLanguage</td><td>string</td><td>O</td><td>예: <code>&#39;ko&#39;</code>, <code>&#39;en&#39;</code></td></tr></tbody></table><p><strong>리턴</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>data</td><td><code>{ user, session } | null</code></td><td>성공 시 생성된 유저/세션 정보</td></tr><tr><td>error</td><td><code>{ message, status } | null</code></td><td>실패 시 에러 (이메일 중복 등)</td></tr></tbody></table><h3 id="signin-상세" tabindex="-1"><code>signIn</code> 상세 <a class="header-anchor" href="#signin-상세" aria-label="Permalink to &quot;`signIn` 상세&quot;">​</a></h3><p><strong>파라미터</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td>email</td><td>string</td><td>O</td><td></td></tr><tr><td>password</td><td>string</td><td>O</td><td></td></tr></tbody></table><p><strong>리턴</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>data</td><td><code>{ user, session } | null</code></td><td>성공 시 로그인된 유저/세션</td></tr><tr><td>error</td><td><code>{ message, status } | null</code></td><td>실패 시 에러 (비밀번호 틀림 등)</td></tr></tbody></table><h2 id="_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록" tabindex="-1">4. 정책/제약 규칙 (미정 항목 — 확정되면 여기 기록) <a class="header-anchor" href="#_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록" aria-label="Permalink to &quot;4. 정책/제약 규칙 (미정 항목 — 확정되면 여기 기록)&quot;">​</a></h2><ul><li><p>[x] <strong>동시 매칭 인원 상한 — 확정 (2026-10-02)</strong>: 기본 3명 + <strong>4단계(자유 채팅) 도달한 매칭마다 +1명</strong>. 관계를 깊게 만들수록 새 매칭 여유가 늘어나는 구조. (무료/유료 세부 — 섹션 5 BM 참고, 기본 3이 무료 기준치)</p></li><li><p>[x] <strong>단계적 소통 해금 규칙 — 구조/수치 확정 (1~4단계), 5단계는 계획만</strong> (2026-10-02)</p><p><strong>설계 원칙</strong></p><ul><li>왜 이 기능이 필요한가: &quot;교환일기 앱&quot; 정체성(비동기·글쓰기 기반)을 지키면서도 사용자의 소통 니즈를 채워주기 위한 절충안.</li><li><strong>&quot;기능 진화&quot;가 아니라 &quot;점진적 추가&quot;</strong>: 다음 단계가 열려도 이전 단계 기능은 없어지지 않고 계속 쌓임 (반응은 4단계 가서도 계속 가능).</li><li><strong>제한 자체가 즐거움</strong>: 짧은 글자수 제한(5자 등)은 &quot;불편해서 참는 것&quot;이 아니라, 트위터·식스워드 스토리처럼 &quot;틀 안에서 압축해서 표현하는 재미&quot;로 설계. 그래서 단계가 올라가도 이전 단계의 제한된 소통 방식을 억지로 없애지 않음.</li><li>왜 앱 안에 머물게 하는가(카톡 등으로 이탈 방지 유인): ① 번역(언어 장벽 해소), ② 앱만의 구조화된 질문-답변 게임 — 카톡엔 없는 두 가지 가치를 마지막 단계까지 유지.</li></ul><p><strong>단계표</strong></p><table tabindex="0"><thead><tr><th>단계</th><th>추가되는 것</th><th>질문 출처</th><th>질문 길이</th><th>답변 길이</th></tr></thead><tbody><tr><td>1</td><td>반응(이모지)</td><td>—</td><td>—</td><td>—</td></tr><tr><td>2</td><td>+ 질문-답변</td><td>앱이 매일 제공</td><td>—</td><td>5자</td></tr><tr><td>3</td><td>+ 질문-답변(서로 작성)</td><td>유저가 직접 작성</td><td>7자</td><td>질문자가 선택: 5자 / 20자 / 100자 (공백 포함)</td></tr><tr><td>4</td><td>+ 자유 채팅</td><td>틀 없음</td><td>—</td><td>제한 없음 (번역 계속 지원)</td></tr><tr><td>5 (계획만, 1차 범위 제외)</td><td>+ 사진 공유</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><ul><li>3단계의 핵심 차이는 글자수가 아니라 <strong>&quot;누가 질문을 만드는지&quot;</strong>(앱 → 유저 자신).</li><li><strong>질문자가 답변 글자수를 직접 선택 가능</strong> (2026-10-02 추가): 질문 만들 때 답변 제한을 셋 중 하나로 고름 — <strong>5자 / 20자 / 100자</strong>(공백 포함, 기존 <code>char_count</code> 계산 방식과 동일). 질문자가 관계 깊이를 스스로 조절하는 느낌을 주기 위함. 100자를 상한으로 둔 이유는 일기 최소 글자수(200자)·4단계(자유 채팅)와 확실히 구분되게 하려는 것 — 3단계가 &quot;틀이 있는 소통&quot;이라는 정체성을 유지.</li><li>DB 설계 시 참고: 질문마다 답변 제한값(5/20/100)을 저장할 필드 필요 — <code>zings</code>/<code>messages</code> 테이블 실제 구현 시 반영.</li><li>4단계는 &quot;질문 틀&quot; 자체가 사라지는 게 핵심 차이 (글자수 제한 철폐는 부수 효과).</li><li>5단계(사진 공유)는 Supabase Storage 등 새 인프라가 필요해 개발 비용이 커서 1차 런칭 범위에서 제외, 자유 채팅(4단계) 이후에 여유 생기면 추가.</li><li>안전장치(신고/차단)는 모든 단계에 무관하게 항상 있어야 함.</li></ul><p><strong>단계 전환 기준 (초안, 조정 가능)</strong></p><table tabindex="0"><thead><tr><th>단계 전환</th><th>조건</th></tr></thead><tbody><tr><td>1 → 2</td><td>매칭 후 <strong>둘 다</strong> 일기 2개 이상 작성</td></tr><tr><td>2 → 3</td><td>매칭 후 <strong>둘 다</strong> 일기 4개 이상 작성</td></tr><tr><td>3 → 4</td><td>매칭 후 <strong>둘 다</strong> 일기 7개 이상 작성</td></tr></tbody></table><ul><li>날짜가 아니라 <strong>&quot;매칭 이후 각자 쓴 일기 개수&quot;</strong> 기준 — 실제 관계 활동량을 더 잘 반영하고, <code>diaries.author_id</code> + <code>created_at</code>으로 매칭 이후 작성분만 세면 돼서 구현도 어렵지 않음.</li><li><strong>&quot;둘 다&quot;</strong> 조건 충족해야 다음 단계로 — 한쪽만 활발하고 한쪽이 방치하면 자연스럽게 관계가 다음 단계로 안 넘어감 (의도된 동작).</li><li>개수는 초안 — 실제 적용 전 재검토 가능.</li></ul></li><li><p>[x] 채팅 기능 범위 — 위 4단계 구조로 확정 (자유, 번역 지원, 인원수/시간 제한 없음)</p></li><li><p>[ ] 글감(프롬프트) 기능 도입 여부 — 일기 작성용 글감이랑, 3단계의 &quot;앱이 매일 질문 제공&quot;은 같은 메커니즘 재사용 가능. 일기 작성용 글감 자체의 도입 여부는 별도 결정 필요.</p></li><li><p>[x] <strong>단계적 공개 기준 — 확정 (2026-10-02)</strong></p><ul><li><strong>전체 공개 시점</strong>: 상호 징 성사 즉시(1단계 진입 시)</li><li><strong>매칭 전 &quot;절반 공개&quot;의 계산 기준</strong>: 글자 수 기준, 정확히 절반 (<code>content.slice(0, Math.floor(char_count / 2))</code>)</li><li>단어/줄 수 기준은 기각 — 화면 크기·폰트·언어(번역)에 따라 결과가 들쭉날쭉해서 플랫폼 간 일관성이 떨어짐. 글자 수는 이미 <code>char_count</code>로 저장 중이라 기존 시스템과도 일치하고 악용(의도적 포맷팅으로 더 많이/적게 보이게 하기)도 어려움.</li></ul></li><li><p>[x] <strong>가입 시 신원 검증 범위 — 확정 (2026-10-02)</strong></p><ul><li>계기: 가짜 신원(소속 거짓 입력 등)으로 가입하는 문제를 어디까지 막을지 논의.</li><li><strong>검증하는 것 — 학교 소속 여부만</strong>: <ul><li>가입 시 이메일 소유 확인 (Supabase Auth &quot;Confirm email&quot; — 개발 중 테스트 편의로 꺼뒀던 것을 <strong>런칭 전 다시 켜야 함</strong>)</li><li>한국 학생(<code>isExchangeStudent: false</code>)은 이메일이 <code>.ac.kr</code>로 끝나는지 추가 체크 (자동 검증 가능)</li><li>교환학생(<code>isExchangeStudent: true</code>)은 국가별 학교 이메일 형식이 제각각이라 도메인 자동 검증은 어려움 — 이메일 소유 확인만 적용, 완전한 소속 검증은 범위 밖</li></ul></li><li><strong>검증 안 하는 것 — 성별/나이 등</strong>: 이메일 인증으로는 애초에 증명 불가능한 영역. 정부 ID 기반 검증은 국가마다 형식이 다르고 민감정보 처리 부담(법적 책임)이 커서 범위 밖으로 판단. 자진 신고 유지 + 신고/차단 기능으로 사후 대응 (에브리타임처럼 서류 업로드 + 사람이 수동 검수하는 방식은, 가입자 늘어날수록 운영 부담이 커서 1인/소규모 팀엔 비현실적이라 채택 안 함).</li><li>결론: <strong>&quot;학교 소속&quot;만 최소한으로 검증하고, 그 외 신원 요소는 자진 신고 + 사후 신고 체계로 간다.</strong></li></ul></li></ul><h2 id="_5-비즈니스-모델-bm-—-방향-확정-2026-10-02-세부-수치-미정" tabindex="-1">5. 비즈니스 모델 (BM) — 방향 확정 (2026-10-02), 세부 수치 미정 <a class="header-anchor" href="#_5-비즈니스-모델-bm-—-방향-확정-2026-10-02-세부-수치-미정" aria-label="Permalink to &quot;5. 비즈니스 모델 (BM) — 방향 확정 (2026-10-02), 세부 수치 미정&quot;">​</a></h2><p>실제 런칭을 염두에 두고 있어서 수익 구조도 고려하되, <strong>매칭/소통의 핵심 경험 자체는 유료화하지 않는다</strong>는 원칙으로 간다. (2026-10-02 수정: 번역은 전면 무료 원칙에서 &quot;일기 번역은 무료 / 채팅 번역은 사용량 제한&quot;으로 세분화)</p><h3 id="전략-핵심-무료-부가-기능-유료-초기엔-전부-무료로-런칭" tabindex="-1">전략: 핵심 무료 + 부가 기능 유료, 초기엔 전부 무료로 런칭 <a class="header-anchor" href="#전략-핵심-무료-부가-기능-유료-초기엔-전부-무료로-런칭" aria-label="Permalink to &quot;전략: 핵심 무료 + 부가 기능 유료, 초기엔 전부 무료로 런칭&quot;">​</a></h3><ol><li><strong>항상 무료</strong>: 일기 작성/조회, <strong>일기 번역</strong>, 소통 단계 해금 1~4단계 진입 자체 — 유료화 대상 아님</li><li><strong>유료화 후보 — 부가/편의 기능</strong>: <ul><li><strong>채팅 번역</strong>: 무료는 하루 N회까지, 초과분은 유료 (정확한 횟수 미정) <ul><li>왜 채팅만: 일기 번역은 &quot;매칭 여부를 결정하는 핵심 진입 경험&quot;이라 막으면 진입장벽이 생김. 채팅 번역은 이미 4단계(둘 다 일기 7개 이상)까지 온 고관여 사용자 대상이라 상대적으로 수용 가능하고, 실시간 대화라 호출량도 일기보다 훨씬 많아서 비용 통제 필요성도 더 큼.</li><li>채팅 자체(글 주고받기)는 계속 무료 — 제한되는 건 &quot;자동 번역 기능&quot;만. 번역 없이 원문으로 채팅하는 건 무제한.</li></ul></li><li><strong>동시 매칭 인원 상한 확장권</strong> (무료 기본 3명 + 4단계 도달 매칭당 +1명 외 추가 확장)</li><li><strong>하루 징 전송 횟수 확장</strong></li><li><strong>단계 스킵권</strong>: 일기 개수 기준 대기를 돈으로 스킵 (예: 2단계 진입까지 기다리는 대신 바로 시작) — 핵심 기능 자체를 막는 게 아니라 &quot;대기 시간을 돈으로 사는&quot; 성격이라 원칙과 덜 충돌한다고 판단</li><li><strong>일기 최대 글자수 확장</strong>: 무료 600자 → 유료 1200자(2배). <strong>최소 글자수(200자)는 유료로도 완화 안 함</strong> — 최소치를 낮추면 &quot;성의 있는 글쓰기&quot;라는 서비스 정체성과 직접 충돌해서 제외, 최대치만 여유를 주는 쪽으로 한정. <ul><li>구현은 결제 시스템 자체가 아직 없어 보류 — <code>users</code> 테이블에 유료 여부 필드 추가 + <code>createDiary</code>/<code>updateDiary</code>의 글자수 검증 로직에서 분기 필요 (결제 기능 만들 때 같이 작업)</li></ul></li><li>프로필 꾸미기, 피드 노출 우선순위 등</li></ul></li><li><strong>런칭 초기엔 위 부가 기능도 전부 무료로 오픈</strong> (사용자 확보 우선) — 단, &quot;런칭 이벤트 기간 무료, 이후 일부 유료 전환 예정&quot;이라고 처음부터 공지해서 나중에 바뀌어도 신뢰 안 깨지게 함</li><li><strong>초기 가입자 혜택 유지 고려</strong>: 서비스 안정화 후 유료 전환 시, 런칭 초기 가입자는 혜택 계속 유지하는 방안 검토</li></ol><h3 id="참고-—-비용-구조상-자연스러운-안전장치" tabindex="-1">참고 — 비용 구조상 자연스러운 안전장치 <a class="header-anchor" href="#참고-—-비용-구조상-자연스러운-안전장치" aria-label="Permalink to &quot;참고 — 비용 구조상 자연스러운 안전장치&quot;">​</a></h3><p>번역 API는 매칭된 상대와 소통할 때만 쓰이므로, &quot;동시 매칭 인원 상한&quot; 정책 자체가 번역 API 사용량(=비용)을 어느 정도 자연스럽게 제어해줌. 채팅 번역 사용량 제한(위 항목)과 별개로, 매칭 상한 자체도 비용 억제에 기여.</p>',51)])])}const p=d(a,[["render",l]]);export{g as __pageData,p as default};
